    ('lv3-01', 'Lesen', 'Übung 1', 0, 'Lesen Sie die Texte und die Aufgaben. Kreuzen Sie an: Richtig oder Falsch.', 'truefalse', '{"passages": [{"paragraphs": [{"t": "Neu! Neu! Neu! Neu! Neu!", "b": true}, {"t": "Liebe Kunden!", "b": false}, {"t": "Ab sofort haben wir auch sonntags von 9–12 Uhr für Sie geöffnet!", "b": false}], "before": 0, "cap": "Vor einem Blumenladen"}, {"paragraphs": [{"t": "Liebe Gäste,", "b": false}, {"t": "im nächsten Monat kocht bei uns ein Koch aus Kalkutta indische Spezialitäten.", "b": false}, {"t": "Wir freuen uns auf Ihren Besuch.", "b": false}], "before": 1, "cap": "Im Restaurant"}, {"paragraphs": [{"t": "Linie 8", "b": true}, {"t": "Ab 1.5. nur bis Hauptbahnhof.", "b": false}, {"t": "Zur Weiterfahrt nach Huchting Linie 1 oder Bus Nr. 53.", "b": false}], "before": 2, "cap": "Bei der Straßenbahn"}, {"paragraphs": [{"t": "Sehr geehrte Interessenten,", "b": false}, {"t": "es gibt leider keine Besichtigungen mehr.", "b": false}, {"t": "Die 3-Zimmer-Wohnung im 3. Stock ist schon vermietet.", "b": false}], "before": 3, "cap": "An einer Haustür"}, {"paragraphs": [{"t": "Sehr geehrte Fahrgäste!", "b": true}, {"t": "Ab 22 Uhr sind unsere Schalter geschlossen.", "b": false}, {"t": "Fahrkarten bekommen Sie dann an unseren Automaten.", "b": false}], "before": 4, "cap": "Im Bahnhof"}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "stil": "schild"}'::jsonb, 23),
