    ('sf1-01', 'Schreiben', 'Übung 1 — Sprachenschule Lingua', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund Marco aus England, geboren am 15.06.1985 in London, möchte im September einen Deutschkurs in Deutschland machen. Er ist Anfänger. Er hat am Nachmittag Zeit. In der Schule hat er Französisch und Spanisch gelernt. Er bekommt ein Anmeldeformular von der Sprachschule Lingua.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Sprachenschule Lingua", "subtitle": "Anmeldung", "rows": [{"label": "Familienname", "val": "Gonman"}, {"label": "Vorname", "blank": 1}, {"label": "Geburtsdatum", "val": "16.06.1985"}, {"label": "Geburtsort", "blank": 2}, {"label": "Muttersprache", "val": "Englisch"}, {"label": "andere Sprachen", "blank": 3}, {"label": "schon Deutsch gelernt?", "blank": 4}, {"label": "Tageszeit", "val": "Nachmittag"}, {"label": "Termin", "blank": 5}]}}'::jsonb, 34),
    ('sf1-02', 'Schreiben', 'Übung 2 — Suchen Sie neue Freunde', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin Malte Rodriguez aus Spanien, geboren am 18. Juli 1982. Seit einem Jahr wohnt sie in Berlin. Sie ist Ärztin und arbeitet im Krankenhaus. Sie liest in der Freizeit Reiseführer im Buchklub Leseratte.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Suchen Sie neue Freunde", "subtitle": "Anmeldung", "rows": [{"label": "Familienname", "val": "Rodriguez"}, {"label": "Vorname", "val": "Malte"}, {"label": "Geburtsdatum", "blank": 1}, {"label": "Geburtsort", "val": "Madrid"}, {"label": "Muttersprache", "val": "Spanisch"}, {"label": "Wohnort", "blank": 2}, {"label": "Geschlecht", "blank": 3}, {"label": "Beruf", "blank": 4}, {"label": "Welche Bücher mögen Sie?", "blank": 5}]}}'::jsonb, 35),
    ('sf1-03', 'Schreiben', 'Übung 3 — Kindergarten Lichtblick', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre russischen Freunde Fiodor und Lana haben eine Tochter. Sie wollen ihre Tochter Anna im Kindergarten anmelden. Der Vater ist Student und er will Sportlehrer werden. Sie wollen ihre Tochter am Vormittag in den Kindergarten bringen, denn ihre Mutter muss am Vormittag zur Arbeit gehen. Anna soll im September in den Kindergarten gehen.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Kindergarten Lichtblick", "subtitle": "Anmeldung", "rows": [{"label": "Familienname", "val": "Pjetrov"}, {"label": "Vorname des Kindes", "blank": 1}, {"label": "Geburtsdatum", "val": "24.02.2009"}, {"label": "Geburtsort", "val": "Moskau"}, {"label": "Muttersprache", "blank": 2}, {"label": "Eintrittstermin", "blank": 3}, {"label": "Alter des Kindes", "val": "5 Jahre"}, {"label": "Beruf des Vaters", "blank": 4}, {"label": "Zeit", "blank": 5}]}}'::jsonb, 36),
    ('sf1-04', 'Schreiben', 'Übung 4 — Die besten Kurse in Hamburg', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin Paola Pini aus Mondenah will nächstes Jahr von 18 bis 31 Oktober in Hamburg einen Exporthandelkurs besuchen. Sie sucht ein Angebot für Übernachtung mit dem Frühstück. Es soll nicht so teuer sein.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Die besten Kurse in Hamburg", "subtitle": "Anmeldung", "rows": [{"label": "Nachname, Vorname", "val": "Pini Paola"}, {"label": "Kurs", "blank": 1}, {"label": "Dauer des Kurses", "blank": 2}, {"label": "Bitte ankreuzen (Zimmer)", "blank": 3}, {"label": "Bitte ankreuzen (Frühstück)", "blank": 4}, {"label": "Wohnort", "blank": 5}]}}'::jsonb, 37),
    ('sf1-05', 'Schreiben', 'Übung 5 — Blumen für Ihre Liebsten', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Kollege Igor Schwerti möchte seiner Mutter Elena Blumen mit einer Geburtstagskarte schicken. Sie hat am Samstag 20.10 Geburtstag. Sie wohnt in den 7. Stock, Ludwigsstr. 8, 14193 Berlin. Seine Mutter ist erst um 14 Uhr zu Hause.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Blumen für Ihre Liebsten", "subtitle": "", "rows": [{"label": "Name, Vorname", "val": "Schwerti,", "blank": 1}, {"label": "Straße / Hausnummer", "val": "Ludwigsstr. 8"}, {"label": "Wohnort", "val": "14193", "blank": 2}, {"label": "Stock", "blank": 3}, {"label": "Geburtstag", "blank": 4}, {"label": "Zeit", "blank": 5}, {"label": "Zahlung", "val": "Kreditkarte (X)"}]}}'::jsonb, 38),
    ('sf1-06', 'Schreiben', 'Übung 6 — Nachhilfeunterricht für Kinder', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund Antonio Verdi möchte seine Kinder (Paula 12 und Pietro 8) bei der Stundenhilfe anmelden. Die Familie ist seit drei Monaten in Deutschland. Beide Kinder brauchen Hilfe bei den Hausaufgaben. Die Tochter Paula in Englisch, der Sohn in Deutsch. Antonio möchte jeden Monat das Geld überweisen.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Nachhilfeunterricht für Kinder", "subtitle": "Anmeldung", "rows": [{"label": "Kind 1 — Nachname, Vorname", "val": "Verdi, Paula"}, {"label": "Alter", "blank": 1}, {"label": "Hilfe in?", "blank": 2}, {"label": "Kind 2 — Nachname, Vorname", "val": "Verdi,", "blank": 3}, {"label": "Alter", "val": "8 Jahre"}, {"label": "Hilfe in?", "blank": 4}, {"label": "Zahlung", "blank": 5}]}}'::jsonb, 39),
    ('sf1-07', 'Schreiben', 'Übung 7 — Reise.com', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Kollege, Markus Schneider macht mit seiner Frau und seinen 3 Töchter (5, 7 und 11 Jahre alt) Urlaub in Spanien. Im Reisebüro bucht er für den nächsten Montag eine Schifffahrt nach Ibiza. Herr Schneider möchte mit der Kreditkarte bezahlen.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Buchen Sie hier Ihren Urlaub, Reise.com", "subtitle": "Anmeldung", "rows": [{"label": "Nachname, Vorname", "val": "Schneider, Markus"}, {"label": "Anzahl der Personen", "blank": 1}, {"label": "Davon Kinder", "blank": 2}, {"label": "Urlaubsort", "blank": 3}, {"label": "Bitte ankreuzen", "blank": 4}, {"label": "Zahlung", "blank": 5}]}}'::jsonb, 40),
