    ('sf1-09', 'Schreiben', 'Übung 9 — Sportclub von 1896', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund Munir Kassem kommt aus Ägypten und wohnt jetzt in Hamburg. Er ist 35 Jahre alt und von Beruf Arzt. In seiner Freizeit will er in einem Verein Fußball spielen. Bezahlen will er mit Kreditkarte.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Sportclub von 1896", "subtitle": "Anmeldung", "rows": [{"label": "Name, Vorname", "val": "Kassem, Munir"}, {"label": "Straße / Hausnummer", "val": "Mundsburger Damm 29"}, {"label": "Wohnort", "val": "22087", "blank": 1}, {"label": "Telefon", "val": "020 / 299 11 45"}, {"label": "E-Mail", "val": "kassem24@web.de"}, {"label": "Beruf", "blank": 2}, {"label": "Alter", "blank": 3}, {"label": "Sport", "blank": 4}, {"label": "Zahlung", "blank": 5}]}}'::jsonb, 42),
    ('sf1-10', 'Schreiben', 'Übung 10 — Sprachschule NEWbornSCHOOL', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin Yvonne Legrand aus Frankreich, geboren am 17.4.1993 in Lyon, möchte vom 1. bis zum 28. August einen Deutschkurs in Deutschland besuchen. Sie hat schon sechs Monate Deutsch gelernt. Sie hat am Vormittag Zeit. In der Schule hat sie Englisch gelernt.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Sprachschule NEWbornSCHOOL", "subtitle": "Anmeldung", "rows": [{"label": "Familienname", "val": "Legrand"}, {"label": "Vorname", "val": "Yvonne"}, {"label": "Geburtsdatum", "val": "17.4.1993"}, {"label": "Geburtsort", "blank": 1}, {"label": "Muttersprache", "val": "Französisch"}, {"label": "Andere Sprachen", "blank": 2}, {"label": "Schon Deutsch gelernt?", "val": "ja"}, {"label": "Wie lange?", "blank": 3}, {"label": "Kurstermin", "blank": 4}, {"label": "Kurszeit", "blank": 5}]}}'::jsonb, 43),
    ('sf1-11', 'Schreiben', 'Übung 11 — Patienteninformation', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund Vladimir Serjakov, 30 Jahre alt, kommt aus Sankt Petersburg in Russland und lebt seit einem Monat in Hamburg. Er hat eine neue Stelle bei TUI als Reiseleiter. Seit gestern hat er 39 Grad Fieber. Heute geht er zum Arzt.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Dr. Arnold Friedrich", "subtitle": "Patienteninformation", "rows": [{"label": "Name, Vorname", "val": "Serjakov, Vladimir"}, {"label": "Telefon", "val": "040 / 456 78 89"}, {"label": "Straße, Hausnummer", "val": "August-Bebel-Str. 22"}, {"label": "Postleitzahl, Wohnort", "val": "20969", "blank": 1}, {"label": "Alter", "blank": 2}, {"label": "Krankenkasse", "val": "AOK"}, {"label": "Beruf", "blank": 3}, {"label": "Seit wann sind Sie krank?", "blank": 4}, {"label": "Was fehlt Ihnen?", "blank": 5}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 44),
    ('sf1-12', 'Schreiben', 'Übung 12 — Ferienwohnung', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund Paolo Pellizzari aus Turin möchte mit seiner Familie (Ehefrau, drei Kinder, 2–7 Jahre alt) an der Ostsee Urlaub machen. Paolo hat drei Wochen Urlaub, vom 25.6. bis zum 15.7. Er sucht eine ruhige Wohnung am Meer, zwei Schlafzimmer, Wohnraum mit Küche, Bad. Paolo will mit dem Auto nach Deutschland kommen.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Ferienwohnung am Meer", "subtitle": "Anmeldung", "rows": [{"label": "Familienname", "val": "Pellizzari"}, {"label": "Vorname", "val": "Paolo"}, {"label": "Anzahl der Personen", "blank": 1}, {"label": "davon Kinder", "blank": 2}, {"label": "Alter der Kinder", "val": "2–7"}, {"label": "Wie viele Schlafzimmer?", "val": "2"}, {"label": "Brauchen Sie eine Küche?", "blank": 3}, {"label": "Anreise", "val": "25. Juni"}, {"label": "Abreise", "blank": 4}, {"label": "Wie reisen Sie an?", "blank": 5}]}}'::jsonb, 45),
