    ('sf1-14', 'Schreiben', 'Übung 14 — Hotel Seeblick', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund, Julian Kirkpatrick, möchte im Hotel Seeblick in Cuxhaven ein Zimmer für sich und seine Frau vom 3.–8. Juni reservieren. Sie möchten nicht im Hotel frühstücken. Er möchte gern einen Fernseher im Zimmer haben und zwei Fahrräder mieten. Julian wohnt in Berlin.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Hotel Seeblick – Cuxhaven", "subtitle": "Reservierung", "rows": [{"label": "Name", "val": "Kirkpatrick"}, {"label": "Vorname", "val": "Julian"}, {"label": "Straße", "val": "Urbanstraße 12"}, {"label": "PLZ / Ort", "val": "10961", "blank": 1}, {"label": "Anreise", "val": "3. Juni"}, {"label": "Abreise", "blank": 2}, {"label": "Zimmer", "blank": 3}, {"label": "Frühstück", "blank": 4}, {"label": "Besondere Wünsche", "blank": 5}]}}'::jsonb, 47),
