    ('sf1-16', 'Schreiben', 'Übung 16 — Anmeldung Sprachzentrum', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund, Juan Rodriguez, geboren am 12.10.1985, möchte einen Deutschkurs an der Volkshochschule machen. Er ist kein Anfänger, er hat schon die A1-Prüfung gemacht. Er ist Taxifahrer von Beruf und arbeitet abends. Er möchte vormittags einen Kurs besuchen. Juan wohnt in München, in der Danklstraße 15. Die Postleitzahl ist 81371.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Anmeldung – Sprachzentrum", "subtitle": "", "rows": [{"label": "Familienname", "val": "Rodriguez"}, {"label": "Vorname", "val": "Juan"}, {"label": "Postleitzahl, Wohnort", "blank": 1}, {"label": "Straße, Hausnummer", "blank": 2}, {"label": "Telefon", "val": "089 / 2935546"}, {"label": "Beruf", "blank": 3}, {"label": "Kurs / Kursnummer", "blank": 4}, {"label": "Termin", "blank": 5}]}}'::jsonb, 49),
