    ('sf1-21', 'Schreiben', 'Übung 21 — Mietvertrag', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund, Ahmet Monsef kommt aus Tehran aus dem Iran. Er ist nicht verheiratet. Seine Familie wohnt in München. Er möchte als Fahrer bei BMW in Deutschland arbeiten. Deshalb möchte er dort eine Wohnung mieten. Er kann monatlich fünfhundertfünfzig Euro Gebühren bezahlen.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Mietvertrag", "subtitle": "Mieter", "rows": [{"label": "Name, Vorname", "val": "Monsef, Ahmet"}, {"label": "geboren am", "val": "21.12.1955"}, {"label": "Wohnort", "blank": 1}, {"label": "Familienstand", "blank": 2}, {"label": "Beruf", "blank": 3}, {"label": "Firma", "blank": 4}, {"label": "Miete", "blank": 5}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 54),
    ('sf1-22', 'Schreiben', 'Übung 22 — Sprachschule Lingua', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin, Ayşe Yılmaz kommt aus Izmir aus der Türkei und hat dort schon etwas Deutsch gelernt. Sie ist jetzt mit ihrem Mann in Berlin. Sie arbeitet nicht. Sie möchte weiter Deutsch lernen. Der Kurs ist von 13 bis 17 Uhr.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Sprachschule Lingua", "subtitle": "Kursteilnehmer", "rows": [{"label": "Name, Vorname", "val": "Yılmaz, Ayşe"}, {"label": "Geburtsort", "blank": 1}, {"label": "Familienstand", "blank": 2}, {"label": "PLZ / Wohnort", "val": "32431 /", "blank": 3}, {"label": "Straße und Hausnummer", "val": "Rosenstraße 17"}, {"label": "Anfänger", "blank": 4}, {"label": "Kurs", "blank": 5}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 55),
    ('sf1-23', 'Schreiben', 'Übung 23 — Sprachkurs', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund Paul kommt aus Puebla in Mexiko und wohnt in der Rosenstraße 22 in Eltville am Rhein. Er möchte in Deutschland von 9 bis 12 Uhr ein Kurs machen. Der Kurs beginnt am 01.06.2015. Er möchte das Geld per Internet überweisen.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Sprachkurs", "subtitle": "Kursteilnehmer", "rows": [{"label": "Name, Vorname", "val": "Ramirez, Paul"}, {"label": "Straße, Hausnummer", "val": "Rosenstraße", "blank": 1}, {"label": "Wohnort", "blank": 2}, {"label": "Monat", "blank": 3}, {"label": "Uhrzeit", "blank": 4}, {"label": "Zahlungsweise", "blank": 5}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 56),
