    ('sf1-25', 'Schreiben', 'Übung 25 — Kindergarten Uesen', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin, Nadja Petrow aus Moskau wohnt in 91207 Lauf. Sie ist eine Sportlehrerin von Beruf und hat einen Sohn. Ihr Sohn Alex ist 3 Jahre alt. Alex muss von 10 bis 12 Uhr den Kindergarten besuchen. Der Kindergarten beginnt ab Dezember.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Kindergarten Uesen", "subtitle": "", "rows": [{"label": "Name, Vorname", "val": "Petrow, Nadja"}, {"label": "Geburtsort", "blank": 1}, {"label": "Beruf", "blank": 2}, {"label": "PLZ / Stadt", "blank": 3}, {"label": "Straße und Hausnummer", "val": "Rosenstraße 17"}, {"label": "Beginn", "blank": 4}, {"label": "Zeit", "blank": 5}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 58),
    ('sf1-26', 'Schreiben', 'Übung 26 — TUI Reisen GmbH', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund Tom, möchte mit seiner Julie und seinem Sohn Chris (8 Jahre alt), am 30.08 ein Ausflug in Stuttgart machen. Von dort wollen Sie zum Urlaub nach Heidelberg fahren.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "TUI Reisen GmbH", "subtitle": "Person", "rows": [{"label": "Name, Vorname", "val": "Müller, Tom"}, {"label": "Partnerin", "blank": 1}, {"label": "Alter der Kinder", "blank": 2}, {"label": "Termin", "blank": 3}, {"label": "Straße und Hausnummer", "val": "Rosenstraße 17"}, {"label": "Ausflugsort", "blank": 4}, {"label": "Urlaubsort", "blank": 5}, {"label": "Gebühren", "val": "350 Euro"}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 59),
    ('sf1-27', 'Schreiben', 'Übung 27 — Stadtführer Deutschland', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin Shelang wohnt in Hamburg. Sie möchte ab August bis Juli am Wochenende einen Kurs machen. Die Kursgebühren möchte sie über Internet überweisen.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Stadtführer Deutschland", "subtitle": "Person", "rows": [{"label": "Name, Vorname", "val": "Shelang"}, {"label": "Wohnort", "blank": 1}, {"label": "Ab Wann", "blank": 2}, {"label": "Bis Wann", "blank": 3}, {"label": "Tag", "blank": 4}, {"label": "Bezahlen", "blank": 5}]}}'::jsonb, 60),
    ('sf1-28', 'Schreiben', 'Übung 28 — Deutsche Bahn AG', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin, Tülay Ateş ist in Berlin und möchte mit ihrer Tochter Melissa nach Bielefeld fahren. Melissa ist 8 Jahre alt. Sie möchte auch einen Sitzplatz im Zug haben.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Deutsche Bahn AG", "subtitle": "Person", "rows": [{"label": "Name", "val": "Ateş"}, {"label": "Vorname", "val": "Tülay"}, {"label": "Anzahl der Personen", "blank": 1}, {"label": "Davon Kinder", "blank": 2}, {"label": "Straße und Hausnummer", "val": "Rosenstraße 17"}, {"label": "PLZ / Ort", "val": "10125 /", "blank": 3}, {"label": "Von Berlin nach", "blank": 4}, {"label": "Sitzplatz fürs Kind", "blank": 5}, {"label": "Gebühren", "val": "350 Euro"}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 61),
    ('sf1-29', 'Schreiben', 'Übung 29 — Kaufvertrag', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund, Ali Hammad wohnt in München. Seine Freundin Agnes Kostmann hat Geburtstag und er möchte ihr ein Geschenk geben. Sie hat ihren Wohnsitz in Salzburg in Österreich.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Kaufvertrag", "subtitle": "Käufer", "rows": [{"label": "Absender", "val": "Hammad, Ali"}, {"label": "Adresse", "val": "Brienner Straße 21"}, {"label": "PLZ / Wohnort", "val": "54678 /", "blank": 1}, {"label": "Empfänger", "blank": 2}, {"label": "Name", "blank": 3}, {"label": "Stadt", "blank": 4}, {"label": "Land", "blank": 5}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 62),
    ('sf2-01', 'Schreiben', 'Übung 1 — Kühlschrank', 0, 'Sie bekommen am Dienstag einen neuen Kühlschrank. Sie müssen arbeiten. Schreiben Sie an Ihren Nachbarn Herrn Maier und bitten Sie um Hilfe. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"passages": [{"paragraphs": [{"t": "Schreibaufgabe", "b": true}, {"t": "Sie bekommen am Dienstag einen neuen Kühlschrank. Sie müssen arbeiten. Schreiben Sie an Ihren Nachbarn Herrn Maier und bitten Sie um Hilfe.", "b": false}, {"t": "Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter):", "b": false}, {"t": "• Warum schreiben Sie?", "b": false}, {"t": "• Uhrzeit?", "b": false}, {"t": "• Schlüssel?", "b": false}], "before": 0}], "criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Uhrzeit?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Schlüssel?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrter Herr Maier,\n\nam Dienstag bekomme ich einen neuen Kühlschrank, aber ich muss arbeiten. Deshalb schreibe ich Ihnen und bitte Sie um Hilfe. Der Kühlschrank wird um 8 Uhr geliefert. Können Sie bitte zu Hause sein? Meinen Schlüssel lege ich in Ihren Briefkasten.\n\nVielen Dank im Voraus.\nMit freundlichen Grüßen\nIhre Nachbarin"}'::jsonb, 63),
    ('sf2-02', 'Schreiben', 'Übung 2 — Arbeit als Verkäufer/in', 0, 'Sie suchen eine Arbeit als Verkäufer/Verkäuferin und lesen in der Zeitung eine Anzeige. Antworten Sie an den Supermarkt „cent". Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"passages": [{"paragraphs": [{"t": "Schreibaufgabe", "b": true}, {"t": "Sie suchen eine Arbeit als Verkäufer/Verkäuferin und lesen in der Zeitung eine Anzeige. Antworten Sie an den Supermarkt „cent\".", "b": false}, {"t": "Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter):", "b": false}, {"t": "• Warum schreiben Sie?", "b": false}, {"t": "• Informationen über sich?", "b": false}, {"t": "• Arbeitszeit?", "b": false}], "before": 0}], "criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Informationen über sich?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Arbeitszeit?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrte Damen und Herren,\n\nich habe Ihre Anzeige in der Zeitung gelesen und suche eine Arbeit als Verkäuferin. Deshalb schreibe ich Ihnen. Ich heiße Sara Ahmad, bin 25 Jahre alt und spreche Arabisch und ein bisschen Deutsch. Wann sind die Arbeitszeiten im Supermarkt?\n\nÜber eine Antwort freue ich mich sehr.\nMit freundlichen Grüßen\nSara Ahmad"}'::jsonb, 64),
    ('sf2-03', 'Schreiben', 'Übung 3 — Treffen absagen', 0, 'Ihre Freundin Nina möchte sich am Samstag mit Ihnen treffen, aber Sie können nicht. Schreiben Sie an Nina. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"passages": [{"paragraphs": [{"t": "Schreibaufgabe", "b": true}, {"t": "Ihre Freundin Nina möchte sich am Samstag mit Ihnen treffen, aber Sie können nicht. Schreiben Sie an Nina.", "b": false}, {"t": "Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter):", "b": false}, {"t": "• Warum schreiben Sie?", "b": false}, {"t": "• Treffen, wann?", "b": false}, {"t": "• Mitbringen?", "b": false}], "before": 0}], "criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Treffen – wann?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Mitbringen?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender (persönlicher) Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Liebe Nina,\n\nwie geht es dir? Leider kann ich mich am Samstag nicht mit dir treffen, weil ich arbeiten muss. Können wir uns am Sonntag um 18 Uhr treffen? Ich bringe einen Kuchen mit. Was möchtest du mitbringen?\n\nBis bald und liebe Grüße\nDeine Freundin"}'::jsonb, 65),
    ('sf2-04', 'Schreiben', 'Übung 4 — Neue Wohnung', 0, 'Sie möchten umziehen und suchen eine neue Wohnung. Sie haben eine Anzeige gelesen. Schreiben Sie an den Vermieter Herrn Mawat. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"passages": [{"paragraphs": [{"t": "Schreibaufgabe", "b": true}, {"t": "Sie möchten umziehen und suchen eine neue Wohnung. Sie haben eine Anzeige gelesen. Schreiben Sie an den Vermieter Herrn Mawat.", "b": false}, {"t": "Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter):", "b": false}, {"t": "• Warum schreiben Sie?", "b": false}, {"t": "• Wohnung sehen, wann?", "b": false}, {"t": "• Adresse?", "b": false}], "before": 0}], "criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Wohnung sehen – wann?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Adresse?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrter Herr Mawat,\n\nich habe Ihre Anzeige im Internet gelesen und suche eine neue Wohnung, weil ich umziehen möchte. Wann kann ich die Wohnung besichtigen? Könnten Sie mir bitte auch die Adresse der Wohnung schicken?\n\nVielen Dank für Ihre Antwort.\nMit freundlichen Grüßen\nIhr(e) ..."}'::jsonb, 66),
    ('sf2-05', 'Schreiben', 'Übung 5 — Geburtstag', 0, 'Sie haben bald Geburtstag und möchten am Freitag feiern. Sie möchten Ihre Freunde Linda und Martin aus dem Sprachkurs einladen. Schreiben Sie an Linda und Martin. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"passages": [{"paragraphs": [{"t": "Schreibaufgabe", "b": true}, {"t": "Sie haben bald Geburtstag und möchten am Freitag feiern. Sie möchten Ihre Freunde Linda und Martin aus dem Sprachkurs einladen. Schreiben Sie an Linda und Martin.", "b": false}, {"t": "Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter):", "b": false}, {"t": "• Warum schreiben Sie?", "b": false}, {"t": "• Uhrzeit?", "b": false}, {"t": "• Musik?", "b": false}], "before": 0}], "criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Uhrzeit?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Musik?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender (persönlicher) Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Liebe Linda, lieber Martin,\n\nich habe bald Geburtstag und möchte am Freitag eine Party machen. Deshalb schreibe ich euch: Ich möchte euch gern einladen! Die Party beginnt um 19 Uhr bei mir zu Hause. Wir hören zusammen klassische Musik. Habt ihr Lust?\n\nIch freue mich auf euch.\nLiebe Grüße\nEuer Freund"}'::jsonb, 67),
    ('sf2-06', 'Schreiben', 'Übung 6 — Abschiedsparty', 0, 'Der Deutschkurs ist zu Ende. Sie machen eine Party und laden Ihre Lehrerin Frau Schmitz ein. Schreiben Sie an Frau Schmitz. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"passages": [{"paragraphs": [{"t": "Schreibaufgabe", "b": true}, {"t": "Der Deutschkurs ist zu Ende. Sie machen eine Party und laden Ihre Lehrerin Frau Schmitz ein. Schreiben Sie an Frau Schmitz.", "b": false}, {"t": "Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter):", "b": false}, {"t": "• Warum schreiben Sie?", "b": false}, {"t": "• Party, wann?", "b": false}, {"t": "• Mitbringen?", "b": false}], "before": 0}], "criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Party – wann?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Mitbringen?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Liebe Frau Schmitz,\n\nunser Deutschkurs ist zu Ende und wir machen eine Party. Deshalb schreibe ich Ihnen: Wir möchten Sie gern einladen! Die Party findet am Samstag um 17 Uhr in der Schule statt. Könnten Sie bitte Getränke und eine Kamera mitbringen?\n\nWir freuen uns auf Sie.\nMit freundlichen Grüßen\nIhre Kursteilnehmer"}'::jsonb, 68)
